// ── 부활 연꽃 아이콘 ──────────────────────────────────────────────────

// 단일 Graphics에 미니 연꽃 그리기 (r = 스케일 단위)
// Graphics는 setRotation 없이 fillPoints를 써야 하므로 꽃잎 좌표를 수동 회전 계산
private _drawLotusIcon(g: Phaser.GameObjects.Graphics, r: number): void {
  const pw = 3.6 * r;
  const ph = 9.0 * r;
  const baseY = 2.5 * r; // 꽃잎 바닥이 모이는 기준점

  // 꽃잎 모양: 양 끝 뾰족한 sin 커브 폴리곤 (중심 원점, 위가 음수)
  const petalPts = (w: number, h: number) => {
    const N = 12;
    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
    }
    for (let i = N - 1; i >= 0; i--) {
      const t = i / N;
      pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
    }
    return pts;
  };

  // 꽃잎 좌표를 rad만큼 회전 후 base 기준으로 offset
  const rotatePetal = (pts: { x: number; y: number }[], rad: number) => {
    const cos = Math.cos(rad), sin = Math.sin(rad);
    const ox = Math.sin(rad) * (ph / 2);
    const oy = baseY - Math.cos(rad) * (ph / 2);
    return pts.map(p => ({
      x: p.x * cos - p.y * sin + ox,
      y: p.x * sin + p.y * cos + oy,
    }));
  };

  // 꽃잎 5장: 바깥 → 안쪽 순서로 그려 레이어링
  const PETAL_DEFS: [number, number, number, number][] = [
    // [angleDeg, wScale, hScale, alpha]
    [ -56, 1.0, 1.0, 0.85 ],
    [  56, 1.0, 1.0, 0.85 ],
    [ -28, 1.0, 1.0, 0.90 ],
    [  28, 1.0, 1.0, 0.90 ],
    [   0, 1.0, 1.0, 0.95 ],
  ];

  PETAL_DEFS.forEach(([deg, ws, hs]) => {
    const rad = deg * Math.PI / 180;
    const raw = petalPts(pw * ws, ph * hs);
    const pts = rotatePetal(raw, rad);
    // 외곽 크림색
    g.fillStyle(0xfff8e7, 0.92);
    g.fillPoints(pts, true);
    // 내부 흰색 하이라이트
    const innerRaw = petalPts(pw * ws * 0.40, ph * hs * 0.70);
    const innerPts = rotatePetal(innerRaw, rad);
    g.fillStyle(0xffffff, 0.55);
    g.fillPoints(innerPts, true);
  });

  // 녹색 꽃받침
  g.fillStyle(0x5aaa55, 0.88);
  g.fillEllipse(0, baseY + ph / 2 - r * 0.5, pw * 3.2, r * 3.2);

  // 금빛 수술
  g.fillStyle(0xffd700, 1);
  g.fillCircle(0, baseY - r * 0.5, r * 2.0);
  g.fillStyle(0xffff99, 0.85);
  g.fillCircle(-r * 0.4, baseY - r * 1.0, r * 0.9);
}

private _createRevivalHeart(scene: Phaser.Scene, px: number, py: number): void {
  if (this.revivalHeart) return;

  const R = 1.25; // 스케일 단위 (총 너비 ~18px)
  const hx = px;
  const hy = py - 52;

  this.revivalHeartGlow = scene.add.image(hx, hy, 'glow_dot')
    .setDepth(499)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xfff0aa)
    .setScale(0.48)
    .setAlpha(0.65);

  this.revivalHeart = scene.add.graphics().setDepth(500).setPosition(hx, hy);
  this._drawLotusIcon(this.revivalHeart, R);

  this.revivalHeartTween = scene.tweens.add({
    targets: [this.revivalHeart, this.revivalHeartGlow],
    scaleX: { from: 0.86, to: 1.14 },
    scaleY: { from: 0.86, to: 1.14 },
    yoyo: true, repeat: -1,
    duration: 700, ease: 'Sine.easeInOut',
  });
}

private _destroyRevivalHeart(scene?: Phaser.Scene): void {
  if (scene && this.revivalHeart) {
    this._spawnLotusBurst(this.revivalHeart.x, this.revivalHeart.y, scene);
  }
  this.revivalHeartTween?.stop();
  this.revivalHeartTween  = null;
  this.revivalHeart?.destroy();
  this.revivalHeart       = null;
  this.revivalHeartGlow?.destroy();
  this.revivalHeartGlow   = null;
}

private _spawnLotusBurst(x: number, y: number, scene: Phaser.Scene): void {
  // 흰색/크림 꽃잎 파편 6개 + 금빛 중앙 플래시
  for (let i = 0; i < 6; i++) {
    const angle = (i / 6) * Math.PI * 2 - Math.PI / 2;
    const g = scene.add.graphics().setDepth(501).setPosition(x, y);
    g.fillStyle(0xfff8e7, 0.95);
    g.fillEllipse(0, 0, Phaser.Math.Between(3, 6), Phaser.Math.Between(6, 11));
    scene.tweens.add({
      targets: g,
      x: x + Math.cos(angle) * Phaser.Math.Between(14, 30),
      y: y + Math.sin(angle) * Phaser.Math.Between(14, 30),
      alpha: 0, scaleX: 0, scaleY: 0,
      duration: Phaser.Math.Between(260, 450),
      ease: 'Quad.easeOut',
      onComplete: () => { if (g.active) g.destroy(); },
    });
  }
  // 금빛 중앙 플래시
  const flash = scene.add.image(x, y, 'glow_dot')
    .setDepth(502)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xffd700)
    .setScale(0.55);
  scene.tweens.add({
    targets: flash, scale: 0, alpha: 0,
    duration: 300, ease: 'Quad.easeOut',
    onComplete: () => { if (flash.active) flash.destroy(); },
  });
}

