268	    const pw = 3.6 * r;
269	    const ph = 9.0 * r;
270	    const baseY = 2.5 * r; // 꽃잎 바닥이 모이는 기준점
271	
272	    // 꽃잎 모양: 양 끝 뾰족한 sin 커브 폴리곤 (중심 원점, 위가 음수)
273	    const petalPts = (w: number, h: number) => {
274	      const N = 12;
275	      const pts: { x: number; y: number }[] = [];
276	      for (let i = 0; i <= N; i++) {
277	        const t = i / N;
278	        pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
279	      }
280	      for (let i = N - 1; i >= 0; i--) {
281	        const t = i / N;
282	        pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
283	      }
284	      return pts;
285	    };
286	
287	    // 꽃잎 좌표를 rad만큼 회전 후 base 기준으로 offset
288	    const rotatePetal = (pts: { x: number; y: number }[], rad: number) => {
289	      const cos = Math.cos(rad), sin = Math.sin(rad);
290	      const ox = Math.sin(rad) * (ph / 2);
291	      const oy = baseY - Math.cos(rad) * (ph / 2);
292	      return pts.map(p => ({
293	        x: p.x * cos - p.y * sin + ox,
294	        y: p.x * sin + p.y * cos + oy,
295	      }));
296	    };
297	
298	    // 꽃잎 5장: 바깥 → 안쪽 순서로 그려 레이어링
299	    const PETAL_DEFS: [number, number, number, number][] = [
300	      // [angleDeg, wScale, hScale, alpha]
301	      [ -56, 1.0, 1.0, 0.85 ],
302	      [  56, 1.0, 1.0, 0.85 ],
303	      [ -28, 1.0, 1.0, 0.90 ],
304	      [  28, 1.0, 1.0, 0.90 ],
305	      [   0, 1.0, 1.0, 0.95 ],
306	    ];
307	
308	    PETAL_DEFS.forEach(([deg, ws, hs]) => {
309	      const rad = deg * Math.PI / 180;
310	      const raw = petalPts(pw * ws, ph * hs);
311	      const pts = rotatePetal(raw, rad);
312	      // 외곽 크림색
313	      g.fillStyle(0xfff8e7, 0.92);
314	      g.fillPoints(pts, true);
315	      // 내부 흰색 하이라이트
316	      const innerRaw = petalPts(pw * ws * 0.40, ph * hs * 0.70);
317	      const innerPts = rotatePetal(innerRaw, rad);
318	      g.fillStyle(0xffffff, 0.55);
319	      g.fillPoints(innerPts, true);
320	    });
321	
322	    // 녹색 꽃받침
323	    g.fillStyle(0x5aaa55, 0.88);
